"""Host-side scorer of llm-looped-token-depth (never mounted into the agent's
container; staged into the Harbor bundle's tests/meta only).

The evaluation process runs submission code (the allocator's decide()) and is
handed label-free requests; it emits predicted choices / generated text.
This module holds the gold answers (labels.json, written by
vendor/data_scripts/nanoGPT/prepare_looped_depth_evals.py --labels-out) and
computes the lm-evaluation-harness 0.4.11 metrics:

    mmlu, commonsense_qa, winogrande   acc
    arc_challenge, hellaswag           acc_norm
    gsm8k (gsm8k_cot)                  exact_match, flexible-extract filter
    bbh (bbh_cot_fewshot, 27 subtasks) exact_match, get-answer filter

Every entry carries the sha256 of the request file it was computed on; a
mismatch against the labels' sha (a request file rebuilt differently) raises.
"""
import json
import re
from pathlib import Path

_HERE = Path(__file__).resolve().parent
_NORM = {"arc_challenge", "hellaswag"}
_FLEX = re.compile(r"(-?[$0-9.,]{2,})|(-?[0-9]+)")
_IGNORE = [",", "\\$", "(?s).*#### ", "\\.$"]
_BBH = re.compile(r"(?<=the answer is )(.*)(?=.)")
_labels = None


def labels():
    global _labels
    if _labels is None:
        _labels = json.loads((_HERE / "labels.json").read_text())
    return _labels


def flexible_extract(resp):
    """lm_eval RegexFilter(regex_pattern=_FLEX, group_select=-1) + take_first."""
    if not isinstance(resp, str):
        resp = ""
    match = _FLEX.findall(resp)
    if not match:
        return "[invalid]"
    match = match[-1]
    if isinstance(match, tuple):
        match = [m for m in match if m]
        match = match[0] if match else "[invalid]"
    return match.strip()


def bbh_extract(resp):
    """lm_eval RegexFilter('(?<=the answer is )(.*)(?=.)', group_select=0) + take_first."""
    if not isinstance(resp, str):
        resp = ""
    match = _BBH.findall(resp)
    if not match:
        return "[invalid]"
    m = match[0]
    if isinstance(m, tuple):
        m = [x for x in m if x]
        m = m[0] if m else "[invalid]"
    return m.strip()


def exact_match(pred, ref):
    for s in _IGNORE:
        pred = re.sub(s, "", pred)
        ref = re.sub(s, "", ref)
    return pred.lower() == ref.lower()


def score_entry(e):
    lab = labels()[e["task"]]
    if e.get("sha") != lab["sha256"]:
        raise ValueError("%s: request file sha %s does not match the labels (%s)"
                         % (e["task"], e.get("sha"), lab["sha256"]))
    gold = lab["labels"][::int(e.get("stride", 1))]
    if e["kind"] == "mc":
        field = "pred_norm" if e["task"] in _NORM else "pred"
        pred = [ord(c) - 48 for c in e[field]]
        if len(pred) != len(gold):
            raise ValueError("%s: %d predictions for %d docs" % (e["task"], len(pred), len(gold)))
        return 100.0 * sum(int(p == g) for p, g in zip(pred, gold)) / len(gold)
    gen = e["gen"]
    if len(gen) != len(gold):
        raise ValueError("%s: %d generations for %d docs" % (e["task"], len(gen), len(gold)))
    if e["task"] == "bbh":
        # metric exact_match with no ignore flags (bbh cot_fewshot template)
        return 100.0 * sum(int(bbh_extract(t) == g) for t, g in zip(gen, gold)) / len(gold)
    return 100.0 * sum(int(exact_match(flexible_extract(t), g)) for t, g in zip(gen, gold)) / len(gold)


def score_payload(payload):
    """{key: accuracy (%)} plus loops_<key> (realised mean loops, unscored)."""
    out = {}
    for key, e in payload["entries"].items():
        out[key] = score_entry(e)
        out["loops_" + key] = float(e["loops"])
    return out

