"""hidden_state_diff baseline for llm-looped-token-depth.

Hidden-state-difference exit (Ouro Sec. 5.4.1, relative form); training-free, minimum depth 2.
The port, its upstream references and every adaptation are documented in the
class docstring of the ported code below.

Replaces the editable DepthAllocator region (lines 23-143) of
edits/depth_allocator.py.
"""

_FILE = "nanoGPT/depth_allocator.py"

_CONTENT = 'class DepthAllocator(nn.Module):
    """Hidden-state-difference exit (Ouro, arXiv:2510.25741, Sec. 5.4.1: exit
    when the change between consecutive recurrent states falls below a
    threshold), in the relative form ||h_t - h_{t-1}|| / ||h_t|| (the same
    form as the 'latent-diff' criterion in Huginn's released code,
    seal-rg/recurrent-pretraining recpre/raven_modeling_minimal.py:2149-2164;
    Huginn's paper criterion, Geiping et al. arXiv:2502.05171 Sec. 6.1, is the
    KL divergence between successive steps' outputs -- a different rule, not
    this arm).  Training-free.  The threshold is calibrated to the budget.
    The first comparison is after step 2 (the input of step 1 is the
    embedding, not a loop state), i.e. minimum depth 2."""

    R_MIN = 2

    def __init__(self, spec):
        super().__init__()
        self.register_buffer("delta", torch.zeros(()))    # = log(threshold)

    def train_step(self, lm, ids, progress):
        return None

    def configure_optimizer(self):
        return torch.optim.AdamW(self.parameters(), lr=1e-3)

    @staticmethod
    def _log_diff(cur, prev):
        cur, prev = cur.float(), prev.float()
        return torch.log((cur - prev).norm(dim=-1) / cur.norm(dim=-1).clamp_min(1e-6) + 1e-12)

    def _full_scores(self, d):
        s = d["states"]
        first = torch.full_like(s[0, :, 0], 1e9, dtype=torch.float32)
        return torch.stack([first, self._log_diff(s[1], s[0]), self._log_diff(s[2], s[1])], 0)

    def decide(self, step, feats):
        if step < self.R_MIN:
            return torch.ones(feats.h.shape[0], dtype=torch.bool, device=feats.h.device)
        st = feats.states
        return self._log_diff(st[step - 1], st[step - 2]) > self.delta

    def calibrate(self, calib, budget):
        self._calibrate_offset(calib, budget)

    # ---- shared calibration: one offset on a per-step "continue" score -------
    TARGET = 0.99            # calibrated realised mean, as a fraction of the budget

    def _sim(self, S, delta):
        """Mean loops if every token followed its full-depth scores S [3, N]."""
        cont = torch.ones(S.shape[1], dtype=torch.bool, device=S.device)
        loops = torch.ones(S.shape[1], device=S.device)
        for t in range(3):
            if t + 1 >= self.R_MIN:
                cont = cont & (S[t] > delta)
            loops = loops + cont.float()
        return float(loops.mean())

    def _solve(self, S, goal):
        lo, hi = float(S.min()) - 1.0, float(S.max()) + 1.0
        for _ in range(60):
            mid = 0.5 * (lo + hi)
            if self._sim(S, mid) > goal:
                lo = mid
            else:
                hi = mid
        return hi

    def _calibrate_offset(self, calib, budget):
        """Offline bisection of the offset on the full-depth scores of the
        calibration tokens, then up to four measured corrections of the goal
        (the adaptive run's states differ from the full-depth ones)."""
        S = torch.cat([self._full_scores(d) for d in calib.trajectories()], 1).float()
        target = self.TARGET * budget
        goal, best = target, None
        for _ in range(4):
            d = self._solve(S, goal)
            self.delta.fill_(d)
            m = calib.measure()
            if m <= 1.005 * budget and (best is None or abs(m - target) < abs(best[1] - target)):
                best = (d, m)
            if abs(m - target) <= 0.003 * budget:
                break
            goal = min(max(goal + (target - m), 1.0), float(MAX_STEPS))
        if best is None:
            d = self._solve(S, max(1.0, goal - 0.05 * budget))
            best = (d, None)
        self.delta.fill_(best[0])
'

OPS = [
    {
        "op": "replace",
        "file": _FILE,
        "start_line": 23,
        "end_line": 143,
        "content": _CONTENT,
    },
]

content.verifier:tests/meta/edits/loop_ipc.py:
"""Wire protocol between the TRUSTED generator (scripts/loop_driver.py: holds
the backbone, runs every forward pass and the decoding loop, never imports
submission code) and the RULE process (scripts/loop_rule.py: imports the
submission's DepthAllocator, holds no backbone weights, runs as its own uid
under Harbor).

One Unix stream socket.  Every message is

    u32 little-endian header length | JSON header | raw tensor bytes

header = {"k": "req" | "rep" | "err", "id": int, "op": str, "m": {...},
          "t": [[name, dtype, [shape...]], ...]}

The payload is the concatenation of the listed tensors' bytes (C order).
No pickle, no code: a header is JSON, a tensor is a whitelisted dtype, a
shape and exactly that many bytes.  The receiving side bounds the header
length, the number of tensors, their rank and the total payload.

Calls nest: while one side waits for the reply to its request it serves the
other side's requests (e.g. the generator asks the rule process for
decide() while serving that process's calib.measure()).  Replies are matched
by id; a reply to anything but the innermost outstanding request is a
protocol error.
"""
from __future__ import annotations

import json
import socket
import struct

import torch

DTYPES = {
    "bool": torch.bool, "uint8": torch.uint8, "int8": torch.int8, "int16": torch.int16,
    "int32": torch.int32, "int64": torch.int64, "float16": torch.float16,
    "bfloat16": torch.bfloat16, "float32": torch.float32, "float64": torch.float64,
}
_NAMES = {v: k for k, v in DTYPES.items()}
MAX_HEADER = 1 << 20
MAX_TENSORS = 16
MAX_RANK = 6


class ProtocolError(RuntimeError):
    pass


class RemoteError(RuntimeError):
    """The other side reported an exception while serving our request."""


def _recv_exact(sock, n, buf=None):
    if buf is None:
        buf = bytearray(n)
    mv = memoryview(buf)
    got = 0
    while got < n:
        k = sock.recv_into(mv[got:], n - got)
        if k == 0:
            raise EOFError("peer closed the connection")
        got += k
    return buf


def _tensor_bytes(t: torch.Tensor):
    t = t.detach()
    if t.device.type != "cpu":
        t = t.cpu()
    t = t.contiguous()
    return memoryview(t.view(torch.uint8).reshape(-1).numpy()) if t.numel() else memoryview(b"")


class Channel:
    """A synchronous, nesting request/reply channel over one socket.

    handlers: op -> fn(meta: dict, tensors: dict) -> (meta, tensors); the
    set can be swapped at any time (`self.handlers = {...}`) to restrict which
    requests the peer may make in the current context.  A request whose op is
    not in the current handler set is answered with an error AND raises
    ProtocolError locally when `strict` (the trusted side).
    """

    def __init__(self, sock: socket.socket, *, max_payload: int, strict: bool, device=None):
        self.sock = sock
        self.max_payload = int(max_payload)
        self.strict = strict
        self.device = device
        self.handlers = {}
        self._next = 1
        self._stack = []
        self.bytes_in = 0
        self.bytes_out = 0
        self.calls_out = 0
        self._pin_out = None      # pinned staging buffers for large CUDA tensors
        self._pin_in = None

    @staticmethod
    def _grow(buf, n):
        if buf is not None and buf.numel() >= n:
            return buf
        n = max(n, 2 * (buf.numel() if buf is not None else 0))
        try:
            return torch.empty(n, dtype=torch.uint8, pin_memory=torch.cuda.is_available())
        except RuntimeError:
            return torch.empty(n, dtype=torch.uint8)

    # ---- framing ------------------------------------------------------------
    def _send(self, kind, mid, op, meta, tensors):
        tensors = tensors or {}
        desc, blobs = [], []
        for name, t in tensors.items():
            if not isinstance(t, torch.Tensor):
                raise TypeError(f"tensor {name!r} is not a torch.Tensor")
            if t.dtype not in _NAMES:
                raise TypeError(f"tensor {name!r}: dtype {t.dtype} not allowed")
            desc.append([str(name), _NAMES[t.dtype], [int(s) for s in t.shape]])
        staged = self._stage(tensors) if tensors else {}
        blobs = [staged[name] for name in tensors]
        hdr = json.dumps({"k": kind, "id": mid, "op": op, "m": meta or {}, "t": desc},
                         separators=(",", ":")).encode()
        self.sock.sendall(struct.pack("<I", len(hdr)) + hdr)
        for b in blobs:
            if len(b):
                self.sock.sendall(b)
        self.bytes_out += len(hdr) + sum(len(b) for b in blobs)

    def _stage(self, tensors):
        """Large CUDA tensors go through one pinned host buffer (16-byte
        aligned slices); everything else through a plain host copy."""
        big = [(n, t) for n, t in tensors.items()
               if isinstance(t, torch.Tensor) and t.is_cuda and t.numel() * t.element_size() >= (1 << 20)]
        if not big:
            return {n: _tensor_bytes(t) for n, t in tensors.items()}
        total = sum(((t.numel() * t.element_size() + 15) // 16) * 16 for _, t in big)
        self._pin_out = self._grow(self._pin_out, total)
        out, off = {}, 0
        for n, t in tensors.items():
            nb = t.numel() * t.element_size() if isinstance(t, torch.Tensor) else 0
            if isinstance(t, torch.Tensor) and t.is_cuda and nb >= (1 << 20):
                sl = self._pin_out[off:off + nb]
                sl.view(t.dtype).view(t.shape).copy_(t.contiguous())
                out[n] = sl
                off += ((nb + 15) // 16) * 16
            else:
                out[n] = None
        torch.cuda.synchronize()
        return {n: (memoryview(v.numpy()) if v is not None else _tensor_bytes(tensors[n])) for n, v in out.items()}

    def _recv(self):
        (n,) = struct.unpack("<I", bytes(_recv_exact(self.sock, 4)))
        if n > MAX_HEADER:
            raise ProtocolError(f"header of {n} bytes")
        try:
            h = json.loads(bytes(_recv_exact(self.sock, n)).decode("utf-8"))
        except (UnicodeDecodeError, ValueError) as exc:
            raise ProtocolError(f"bad header: {exc}") from None
        if not isinstance(h, dict) or h.get("k") not in ("req", "rep", "err"):
            raise ProtocolError("bad header")
        kind, mid, op, meta, desc = h["k"], h.get("id"), h.get("op"), h.get("m"), h.get("t")
        if (not isinstance(mid, int) or not isinstance(op, str) or len(op) > 64
                or not isinstance(meta, dict) or not isinstance(desc, list) or len(desc) > MAX_TENSORS):
            raise ProtocolError("bad header fields")
        specs, total = [], 0
        for d in desc:
            if (not isinstance(d, list) or len(d) != 3 or not isinstance(d[0], str) or len(d[0]) > 64
                    or d[1] not in DTYPES or not isinstance(d[2], list) or len(d[2]) > MAX_RANK
                    or not all(isinstance(s, int) and 0 <= s < (1 << 40) for s in d[2])):
                raise ProtocolError("bad tensor descriptor")
            dt = DTYPES[d[1]]
            numel = 1
            for s in d[2]:
                numel *= s
            nb = numel * torch.empty((), dtype=dt).element_size()
            total += nb
            specs.append((d[0], dt, d[2], nb))
        if total > self.max_payload:
            raise ProtocolError(f"payload of {total} bytes > {self.max_payload}")
        tensors = {}
        cuda = self.device is not None and str(self.device).startswith("cuda")
        for name, dt, shape, nb in specs:
            if nb and cuda and nb >= (1 << 20):
                self._pin_in = self._grow(self._pin_in, nb)
                sl = self._pin_in[:nb]
                _recv_exact(self.sock, nb, memoryview(sl.numpy()))
                t = sl.view(dt).reshape(shape).to(self.device)     # blocking copy: the buffer is reused
            elif nb:
                raw = _recv_exact(self.sock, nb)
                t = torch.frombuffer(raw, dtype=torch.uint8).view(dt).reshape(shape)
                if self.device is not None:
                    t = t.to(self.device)
            else:
                t = torch.empty(shape, dtype=dt, device=self.device)
            tensors[name] = t
        self.bytes_in += n + total
        return kind, mid, op, meta, tensors

    # ---- request / reply -----------------------------------------------------
    def call(self, op, meta=None, tensors=None):
        mid = self._next
        self._next += 1
        self._stack.append(mid)
        self.calls_out += 1
        try:
            self._send("req", mid, op, meta, tensors)
            while True:
                kind, rid, rop, rmeta, rt = self._recv()
                if kind == "req":
                    self._serve(rid, rop, rmeta, rt)
                    continue
                if rid != mid:
                    raise ProtocolError(f"reply to {rid} while waiting for {mid}")
                if kind == "err":
                    raise RemoteError(f"{op}: {str(rmeta.get('error', ''))[:4000]}")
                return rmeta, rt
        finally:
            self._stack.pop()

    def _serve(self, rid, op, meta, tensors):
        fn = self.handlers.get(op)
        if fn is None:
            self._send("err", rid, op, {"error": f"request {op!r} is not allowed here"}, None)
            if self.strict:
                raise ProtocolError(f"peer made a request that is not allowed here: {op!r}")
            return
        try:
            rmeta, rt = fn(meta, tensors)
        except Exception as exc:          # reported to the peer, re-raised on the trusted side
            try:
                self._send("err", rid, op, {"error": f"{type(exc).__name__}: {exc}"}, None)
            except OSError:
                pass
            if self.strict:
                raise
            return
        self._send("rep", rid, op, rmeta, rt)

    def serve_forever(self, until=lambda: False):
        """The rule process's main loop: serve requests until `until()`."""
        while not until():
            kind, rid, op, meta, tensors = self._recv()
            if kind != "req":
                raise ProtocolError("unexpected reply")
            self._serve(rid, op, meta, tensors)

